-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "Fire"
L["rm.era.mage.fire.Description"] = "Fire from level 10 to 60, chosen when you have Fire points and none in Frost, or Fire is your main tree. Pyroblast (else Fireball) opens; Pyroblast after Presence of Mind; Scorch keeps five Fire Vulnerability stacks with Improved Scorch on targets that will live; Fire Blast and Scorch finish; Fireball fills. Three or more engaged enemies: Blast Wave, Flamestrike, Arcane Explosion, Cone of Cold, Blizzard. Reminders: Combustion at five Scorch stacks on elites and long fights, armor, Arcane Intellect, mana gems, Ice Barrier, Mana Shield, Evocation, Counterspell, Remove Lesser Curse, Ice Block, Presence of Mind. Off by default: weaving Fire Blast whenever it is ready."
L["rm.era.mage.fire.warcrafttavern.Name"] = "Fire (Warcraft Tavern)"
L["rm.era.mage.fire.warcrafttavern.Description"] = "Fire after Warcraft Tavern, an alternative to the recommended Fire premade, off by default: enable it and disable that one, or raise its priority. Combustion is spent at the pull on elites and bosses instead of waiting for Scorch stacks; Pyroblast opens; Scorch keeps five stacks with Improved Scorch; Fireball fills; Fire Blast only while moving. Packs: Flamestrike first, then Arcane Explosion, Cone of Cold and Blast Wave close in, Blizzard at range. Same reminders as the Fire premade."
L["rm.era.mage.frost.Name"] = "Frost"
L["rm.era.mage.frost.Description"] = "Frost from level 1 to 60, also for Arcane builds and the Mage default before talents. Frostbolt (Fireball before level 4); Frost Nova when a mob reaches you, except on raid bosses; Arcane Missiles once a mob reaches you if you have Improved Arcane Missiles; Cone of Cold, Arcane Explosion and Blizzard when three or more enemies are engaged; Fire Blast while moving with mana to spare; Fire Blast and the wand finish ordinary mobs when solo; wand when out of mana. Reminders: armor (Ice Armor solo, Mage Armor in a group, never replacing one you chose), Arcane Intellect, conjuring and using mana gems, Ice Barrier, Mana Shield, Evocation, Counterspell, Remove Lesser Curse, Ice Block, Cold Snap, Arcane Power and Presence of Mind. Off by default: the Shatter Flamestrike and rank-1 Frostbolt to stack Winter's Chill. Blink, Polymorph, kiting and target choice stay with you."
L["rm.era.mage.frost.icyveins.Name"] = "Frost AoE grinding (Icy Veins)"
L["rm.era.mage.frost.icyveins.Description"] = "Blizzard leveling after Icy Veins' AoE grinding guide, chosen automatically when you play solo with Improved Blizzard. From two engaged enemies: Frost Nova the pack, Cone of Cold while Nova is cooling, Blizzard once nothing is next to you, Arcane Explosion when they are; Frostbolt on a single target, Fire Blast and the wand to finish. Mana Shield and Ice Barrier go up before each pull. Gathering the pack, Blink and kiting stay with you."
L["rm.forever.mage.arcane.Name"] = "Arcane"
L["rm.forever.mage.arcane.Description"] = "Arcane once Arcane is your main talent tree with 11 points and you know Arcane Blast. Pulls with Frostbolt solo or Arcane Blast in a group; then Arcane Missiles on Missile Barrage, Arcane Blast on Clearcasting, Arcane Wrath at three Arcane Blast stacks, Arcane Blast up to four stacks on elites and two on other targets while you can afford it (mana is hidden on Forever), then Frostfire Bolt, Frostbolt or Fireball to fish for Missile Barrage, and a wand when solo and you cannot afford a spell. Without Arcane Wrath (the older beta design) Fire Blast spends the stacks. Moving: Fire Blast. Three or more enemies fighting you: Arcane Explosion. Reminders: Presence of Mind and Arcane Power on elites (Arcane Power no longer waits for half your mana), plus the Mage upkeep reminders."
L["rm.forever.mage.fire.Name"] = "Fire"
L["rm.forever.mage.fire.Description"] = "Fire once Fire is your main talent tree with 11 points (Pyroblast's tier). Pulls with Pyroblast on elites, else Frostfire Bolt or Fireball; then Pyroblast at three Heating Up stacks, Ice Lance on Fingers of Frost or a frozen target (Fire/Frost hybrids), Fire Blast on cooldown, Scorch to keep your five Fire Vulnerability stacks on elites, Frostfire Bolt (from 40) or Fireball, wand when solo and you cannot afford a spell. Moving: Fire Blast or Ice Lance. Four or more enemies fighting you: Flamestrike, Blast Wave, Arcane Explosion. Scorch starts the stacks only once you have Improved Scorch; a close-range Scorch is off until you enable it. Reminders: Combustion and Presence of Mind on elites, plus the Mage upkeep reminders."
L["rm.forever.mage.fire.icyveins.Name"] = "Fire leveling (Icy Veins)"
L["rm.forever.mage.fire.icyveins.Description"] = "Icy Veins' Fire leveling build without Improved Scorch, an alternative to the recommended Fire premade, off by default: enable it and disable that one, or raise its priority. Pulls with Pyroblast, uses Fire Blast to spend Wake of Fire, Scorch as the mob closes (target health is hidden on Forever, so its low-target finishers are yours), then Frostfire Bolt (from 40) or Fireball. Same AoE, movement, wand and reminders as the Fire premade, without Combustion and Presence of Mind."
L["rm.forever.mage.frost.Name"] = "Frost"
L["rm.forever.mage.frost.Description"] = "Frost from level 1 to 60, and the Forever Mage default before talent spells (Fireball until Frostbolt at level 4). Pulls with Frostbolt; then Ice Lance on Fingers of Frost or a frozen target (also while Frostbolt is still casting, to cancel or batch), Cone of Cold at five Winter's Chill stacks, Arcane Missiles on Missile Barrage, Frostbolt, and a wand when solo and you cannot afford Frostbolt. Moving: Ice Lance, else Fire Blast. Three or more enemies fighting you: Cone of Cold; five or more: Blizzard, or Arcane Explosion with a mob on you. Warcraft Tavern's Flamestrike and Arcane Explosion AoE is included but off. Reminders: Arcane Intellect, armor (Ice or Frost solo, Mage Armor in a group, never replacing one you chose), Ice Barrier, Counterspell, Remove Lesser Curse, Frost Nova when a mob reaches you, Cold Snap. Health and mana are hidden from addons on Forever, so finishing low targets with Fire Blast, Evocation and Ice Block are your call; Blink, kiting, Polymorph and mana gems stay with you too."
L["rm.mop.mage.arcane.Name"] = "Recommended"
L["rm.mop.mage.arcane.Description"] = "Recommended for Arcane, from level 10 to 90 (selected in the Arcane specialization). Arcane Blast builds four Arcane Charges; with four, an Arcane Missiles! proc is spent with Missiles, and without one Arcane Barrage comes out once your mana drops below 90%. Above 95% mana it keeps blasting, which is how the simulator plays it. Missiles is never left sitting on two procs, Barrage is cast before Alter Time snaps back, and with two or more enemies Barrage goes out every four charges; Cone of Cold and Arcane Explosion when five are close. Keeps your talented bomb up, and Fire Blast or Ice Lance while moving without Ice Floes. Reminders: Arcane Power and Alter Time at four charges with a proc, Frost Armor (Molten before 54), Arcane Brilliance, Counterspell, Mana Gem, Mirror Image, Ice Barrier, Ice Floes, Rune of Power or Invocation. Time Warp, Spellsteal and Presence of Mind are off; Rune of Power still needs placing by hand."
L["rm.mop.mage.arcane.icyveins.Name"] = "Barrage at four charges (Icy Veins)"
L["rm.mop.mage.arcane.icyveins.Description"] = "The guides' Arcane rule (Icy Veins, Wowhead, Method, wowtbc.gg), an alternative to the recommended Arcane premade: at four Arcane Charges, Arcane Missiles if a proc is up, otherwise Arcane Barrage, whatever your mana; Missiles only at four charges. Everything else (Alter Time, bombs, AoE, moving, reminders) matches the recommended one, except that Arcane Power is suggested at four charges without waiting for a proc. Off by default: enable it and disable the recommended Arcane premade, or raise its priority."
L["rm.mop.mage.fire.Name"] = "Recommended"
L["rm.mop.mage.fire.Description"] = "Recommended for Fire, from level 10 to 90 (selected in the Fire specialization). Opens with a hard Pyroblast, then Inferno Blast (Fire Blast before 24) turns Heating Up into a Pyroblast! proc, which is cast at once unless Combustion is about to come off cooldown; then it waits for the next Heating Up while you cast Fireball. Combustion lights right after a Pyroblast while Ignite and the Pyroblast burn are on the target; the addon cannot see how big Ignite is, so judge a weak one yourself. Keeps your talented bomb up, spreads with Inferno Blast when two or more enemies fight you, Cone of Cold and Arcane Explosion for five close by, Scorch on the move. Reminders: Molten Armor, Presence of Mind, Alter Time with both procs, Mana Gem, Arcane Brilliance, Counterspell, Mirror Image, Ice Barrier, Ice Floes, Invocation or Rune of Power. Dragon's Breath, Time Warp and Spellsteal are off."
L["rm.mop.mage.fire.icyveins.Name"] = "Hold Pyroblast! (Icy Veins)"
L["rm.mop.mage.fire.icyveins.Description"] = "Icy Veins', Method's and wowtbc.gg's Fire play, an alternative to the recommended Fire premade: a Pyroblast! proc is held until a Heating Up joins it, then cast together with your Fireball, and spent alone only when it is about to expire. Everything else matches the recommended one. Off by default: enable it and disable the recommended Fire premade, or raise its priority."
L["rm.mop.mage.frost.Name"] = "Recommended"
L["rm.mop.mage.frost.Description"] = "Frost from level 10 to 90 (selected in the Frost specialization). Ice Lance at two Fingers of Frost, Frostfire Bolt on Brain Freeze, your talented bomb, Frozen Orb, Ice Lance on one Fingers of Frost, Frostbolt; from 87 a proc is held for Alter Time when it is less than 10 seconds away. With two or more enemies: Frozen Orb, Cone of Cold and Arcane Explosion when they are close, Blizzard when four stand still. Ice Lance and Fire Blast on the move without Ice Floes. Reminders: Water Elemental, Freeze on anything but a boss (place it yourself), Icy Veins timed with Alter Time, Alter Time at two Fingers of Frost in Icy Veins, Frost Armor (Molten before 54), Mana Gem, Arcane Brilliance, Counterspell, Mirror Image, Ice Barrier, Ice Floes, Invocation or Rune of Power. Cold Snap, Presence of Mind, Time Warp and Spellsteal are off."
L["rm.mop.mage.unspecialized.Name"] = "Before a specialization"
L["rm.mop.mage.unspecialized.Description"] = "For levels 1 to 9, and any Mage who has not chosen a specialization yet. Frostfire Bolt, Fire Blast to finish a target or on the move, Ice Lance on the move once learned, Arcane Explosion when three or more enemies are in melee range. Reminders: Frost Nova when a mob reaches you, Counterspell, and Molten Armor and Arcane Brilliance if you reach them. Choosing a specialization at 10 switches to that specialization's premade."
L["rm.retail.mage.arcane.Name"] = "Blizzard Assisted"
L["rm.retail.mage.arcane.Description"] = "Recommended for Arcane. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what Assisted Combat leaves to you: Arcane Surge in combat, Arcane Intellect out of combat, Counterspell on an interruptible cast, Prismatic Barrier whenever it is ready in combat, and your racial cooldown in combat. Enemy casts are hidden in combat, so Counterspell lights only where the game shows them; health is hidden on Retail, so Ice Block and other emergency buttons are your call. Mirror Image, Alter Time, Blink and trinkets stay with you."
L["rm.retail.mage.arcane.guide.Name"] = "Reference (Icy Veins and SimulationCraft)"
L["rm.retail.mage.arcane.guide.Description"] = "Reference only, off by default: the guides' Arcane priority. Arcane Salvo and Clearcasting are hidden from addons in Midnight combat (only Arcane Charges stay visible), so it cannot run there; mana is hidden on Retail, so the low-mana Evocation is yours; read it, or clone it to experiment. Pulls with Arcane Blast. Sunfury: Arcane Missiles on Clearcasting below 12 Salvo, Prismatic Bolt outside Arcane Soul, Arcane Barrage at four charges with 12 Salvo and Clearcasting or 25 Salvo, or with Arcane Soul at any charge count, Prismatic Bolt, Arcane Orb below three charges, Arcane Pulse on three enemies or at no charges, Arcane Blast. Spellslinger (Splintering Sorcery known): Prismatic Bolt, Orb on packs, Barrage at 20 Salvo (only at four charges against two or more enemies), Missiles on Clearcasting below 15 Salvo, Orb and Pulse below three charges (no Pulse in Arcane Surge), Arcane Blast. Arcane Barrage when Blast cannot be cast. Reminders: Arcane Surge, Touch of the Magi after a Barrage or Prismatic Bolt in or well before Surge, Presence of Mind at no charges after a Barrage, plus the Assisted premade's reminders."
L["rm.retail.mage.fire.Name"] = "Blizzard Assisted"
L["rm.retail.mage.fire.Description"] = "Recommended for Fire. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what Assisted Combat leaves to you: Combustion in combat, Arcane Intellect out of combat, Counterspell on an interruptible cast, Blazing Barrier whenever it is ready in combat, and your racial cooldown in combat. Enemy casts are hidden in combat, so Counterspell lights only where the game shows them; health is hidden on Retail, so Ice Block and other emergency buttons are your call."
L["rm.retail.mage.fire.guide.Name"] = "Reference (Icy Veins, Wowhead and SimulationCraft)"
L["rm.retail.mage.fire.guide.Description"] = "Reference only, off by default: the guides' Fire priority. Hot Streak, Heating Up, Pyroclasm and Fire Blast charges are hidden in Midnight combat, so it cannot run there. Fire Blast while a cast is finishing to turn Heating Up into Hot Streak; pulls with Pyroblast. Pyroblast (Flamestrike on four or more enemies) on Hyperthermia, Meteor, Pyroblast on Hot Streak, Fire Blast on Heating Up inside Combustion, Pyroblast on Pyroclasm, Scorch on Heat Shimmer or while moving, Fire Blast on Heating Up, then Frostfire Bolt or Fireball. Reminders: Combustion as a hard cast finishes, Blazing Barrier and the utility reminders. Waiting for Firestarter and timing Meteor into Combustion stay with you."
L["rm.retail.mage.frost.Name"] = "Blizzard Assisted"
L["rm.retail.mage.frost.Description"] = "Recommended for Frost. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what Assisted Combat leaves to you: Summon Water Elemental when you have the talent and no elemental, Arcane Intellect out of combat, Counterspell on an interruptible cast, Ice Barrier whenever it is ready in combat, and your racial cooldown in combat. Enemy casts are hidden in combat, so Counterspell lights only where the game shows them; health is hidden on Retail, so Ice Block and other emergency buttons are your call."
L["rm.retail.mage.frost.guide.Name"] = "Reference (Icy Veins and SimulationCraft)"
L["rm.retail.mage.frost.guide.Description"] = "Reference only, off by default: the guides' Frost priority for each hero tree. Procs, Freezing stacks and cooldowns are hidden in Midnight combat, so it cannot run there. Pulls with Frostfire Bolt or Frostbolt. Frostfire (Frostfire Bolt known): Glacial Spike when ready, Comet Storm on one or two enemies, Flurry on Brain Freeze without Thermal Void, Ice Lance on two Fingers of Frost, Ray of Frost, Frozen Orb, Blizzard on Freezing Rain with three enemies, Ice Lance on Fingers of Frost with Thermal Void or at twelve Freezing, Flurry, Ice Nova or Cone of Cold on five, then Glacial Spike or Frostfire Bolt. Spellslinger: Comet Storm, Flurry on Brain Freeze, Ice Lance on two Fingers, Frozen Orb, Glacial Spike when ready, Blizzard on Freezing Rain, Ice Lance on Fingers of Frost or six Freezing, Ray of Frost, Flurry, Ice Nova or Cone of Cold on four, Blizzard on seven, then Glacial Spike or Frostbolt. Ice Lance while moving. Reminders: Summon Water Elemental, Ice Barrier and the utility reminders."
L["rm.retail.mage.initial.Name"] = "Blizzard Assisted"
L["rm.retail.mage.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Mage's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Mage premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.sod.mage.arcane.Name"] = "Arcane (SoD)"
L["rm.sod.mage.arcane.Description"] = "Season of Discovery Arcane damage, chosen when Arcane is your main tree and Arcane Blast is engraved. Arcane Missiles on Missile Barrage; Arcane Barrage at four Arcane Blast stacks; Balefire Bolt when safe, never at four Balefire stacks or more; Living Flame on cooldown; Arcane Blast fills. Arcane Barrage and Fire Blast while moving; Living Flame and Arcane Explosion on packs. Reminders: Arcane Power on elites and long fights, Presence of Mind with Arcane Power or while moving, Icy Veins, Cold Snap and the other Mage reminders."
L["rm.sod.mage.fire.Name"] = "Fire (SoD)"
L["rm.sod.mage.fire.Description"] = "Season of Discovery Fire from level 1 to 60, and the Mage default there. Uses the runes you have engraved: Pyroblast on Hot Streak at once; Living Bomb kept on targets that will live; Scorch with Improved Scorch while Fire Vulnerability is below two stacks or about to fade; Living Flame on cooldown; Balefire Bolt at five Fire Vulnerability stacks, never at four Balefire stacks or more (the fifth kills you); Frostfire Bolt, else Fireball. Living Bomb, Living Flame and Fire Blast while moving; Living Flame, Living Bomb, Blast Wave, Cone of Cold, Flamestrike and Blizzard on packs. Reminders: Fire Blast with Overheat, Combustion, Icy Veins and Cold Snap, Molten or other armor, Arcane Intellect, mana gems, Ice Barrier, Mana Shield, Evocation, Counterspell, curse removal, Ice Block. Spreading Living Bomb across targets stays with you."
L["rm.sod.mage.frost.Name"] = "Frost (SoD)"
L["rm.sod.mage.frost.Description"] = "Season of Discovery Frost from level 10, chosen when Frost is your main tree. Fingers of Frost goes into Ice Lance at three or more of your Glaciate stacks, otherwise into Deep Freeze; Balefire Bolt on a Brain Freeze proc and otherwise when safe, never at four Balefire stacks or more; Living Bomb and Living Flame when engraved; Spellfrost Bolt, else Frostfire Bolt, else Frostbolt. Ice Lance, Frozen Orb, Living Bomb and Fire Blast while moving; Frozen Orb, Living Flame, Living Bomb, Blizzard and Cone of Cold on packs. Reminders: Frozen Orb, Icy Veins, Cold Snap, armor, mana gems and the other Mage reminders. Queuing a spell as a bolt lands stays with you."
L["rm.sod.mage.frost.warcrafttavern.Name"] = "Frost, Fire runes (SoD, Warcraft Tavern)"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "Warcraft Tavern's Phase 4 Frost build on Fire runes, an alternative to the recommended Season of Discovery Frost premade, off by default: enable it and disable that one, or raise its priority. Pyroblast opens; Pyroblast on Hot Streak; Living Bomb kept up; Scorch to five stacks with Improved Scorch; Balefire Bolt only on a Brain Freeze proc and never at four Balefire stacks or more; Frostfire Bolt fills. Living Bomb and Fire Blast while moving; Living Bomb, Cone of Cold and Blizzard on packs. Reminders: Fire Blast with Overheat, Frozen Orb during Icy Veins, Icy Veins, Cold Snap and the other Mage reminders."
L["rm.sod.mage.healer.Name"] = "Healer (SoD)"
L["rm.sod.mage.healer.Description"] = "Season of Discovery Mage healing, chosen when Regeneration or Mass Regeneration is engraved. With a friendly target: Rewind Time and Chronostatic Preservation below half health, Regeneration when your Temporal Beacon is missing, Mass Regeneration, Temporal Anomaly. With an enemy target, damage that heals your beacons: Spellfrost Bolt for Frost healers, otherwise Arcane Missiles on Missile Barrage, Arcane Barrage at two Arcane Blast stacks, Balefire Bolt when safe (never at four Balefire stacks or more) and Arcane Blast. Reminders: Arcane Power, Presence of Mind, Frozen Orb and the other Mage reminders. Off by default: Arcane Explosion on packs, and Ice Lance and Deep Freeze for Frost healers. While you channel Mass Regeneration the next spell already shows, so you can cancel it at once (its direct healing is small). Choosing whom to heal stays with you."
L["rm.tbc.mage.arcane.Name"] = "Arcane"
L["rm.tbc.mage.arcane.Description"] = "Arcane, chosen when Arcane is your main talent tree. Before level 64: Arcane Missiles, with Frostbolt when mana runs low. From 64: Arcane Blast while burning (Arcane Power, Bloodlust or above 35% mana), otherwise three Arcane Blast stacks and Frostbolt until they are about to drop. Arcane Explosion and Cone of Cold for three or more enemies. Reminders include Arcane Power, Presence of Mind, mana gem and Evocation."
L["rm.tbc.mage.fire.icyveins.Name"] = "Fire (Icy Veins)"
L["rm.tbc.mage.fire.icyveins.Description"] = "Fire after Icy Veins, chosen when Fire is your main talent tree. Pyroblast opens a pull once learned, Improved Scorch keeps five Fire Vulnerability stacks, Fireball fills, Fire Blast is for moving; Blast Wave, Dragon's Breath and Flamestrike for three or more enemies. Reminders: Molten, Mage or Ice Armor, Combustion below 20% target health, mana gem, Evocation and the shared Mage utilities."
L["rm.tbc.mage.fire.wowhead.Name"] = "Fire (Wowhead)"
L["rm.tbc.mage.fire.wowhead.Description"] = "Fire after Wowhead and simulator. Like the Icy Veins Fire premade, but it weaves Fire Blast whenever it is ready while you stand still (more damage, more mana) and opens with Fireball instead of Pyroblast. An alternative to the recommended Icy Veins Fire premade, off by default: enable it and disable that one, or raise its priority."
L["rm.tbc.mage.frost.Name"] = "Frost"
L["rm.tbc.mage.frost.Description"] = "Frost from level 1 to 70, and the Mage default before talents. Frostbolt (Fireball before level 4), Frost Nova when something hits you, Cone of Cold with Blizzard or Arcane Explosion when three or more enemies are engaged, Ice Lance on frozen targets and while moving, wand when out of mana. Reminders: armor, Arcane Intellect, mana gem, Evocation, Counterspell, Spellsteal, Ice Barrier, Icy Veins, Cold Snap and Water Elemental. Blink, Ice Block, kiting and target choice stay with you."
